   if (!esmEntry) {
     esmEntry = packageJson.module || packageJson.main;
   }

   if (!esmEntry) {
     throw new Error(`Cannot find ESM entry point in ${packageName}/package.json`);
   }

   return path.join(packageDir, esmEntry);
